"""Add members' verdicts on Doctor insights.

Revision ID: 0704
Revises: 0703
Create Date: 2026-10-16

`insight_feedback` holds one verdict (`right` or `wrong`, with an optional note) per member per
insight, so the Doctor's precision per detector kind can be measured from what people said
about its findings.

Choices worth knowing about:

* Ids are UUIDv7 generated by the application, so `id` has no default.
* The insight is referenced by the composite key `(insight_id, project_id)`, as
  `insight_explanations` does (0403), so a vote can never point at another project's insight.
  The key is added `NOT VALID` and then validated inside the worker bypass (the `_validate`
  wrapper of 0508), the rule every validation follows; the table is new, so the scan is empty.
* `UNIQUE (project_id, insight_id, user_id)` (`insight_feedback_vote_key`) keeps one verdict per
  user per insight; the application upserts on it, so a second vote replaces the first.
* A deleted insight or user takes its votes with it (`ON DELETE CASCADE`): a vote by nobody is
  not kept. `(user_id)` is indexed so deleting a user does not scan the table.
* `note` is at most 500 characters. Row-level security is ENABLE + FORCE with the project
  isolation and worker bypass policies in the exact form of every project table (0505).

A new table in one transaction, under the 5 second lock wait cap (the foreign keys take brief
locks on `projects`, `users` and `insights`). Downgrade drops the table and the votes with it.
"""

from collections.abc import Sequence

from alembic import op

revision: str = "0704"
down_revision: str | None = "0703"
branch_labels: str | Sequence[str] | None = None
depends_on: str | Sequence[str] | None = None

LOCK_TIMEOUT = "5s"
TABLE = "insight_feedback"
INSIGHT_FK = "insight_feedback_insight_fkey"
PROJECT_EXPRESSION = (
    "project_id = (SELECT NULLIF(current_setting('app.project_id', true), '')::uuid)"
)
BYPASS_EXPRESSION = "(SELECT current_setting('app.bypass_rls', true)) = 'on'"


def upgrade() -> None:
    op.execute(f"SET LOCAL lock_timeout = '{LOCK_TIMEOUT}'")
    op.execute(
        f"""
        CREATE TABLE {TABLE} (
            id          uuid PRIMARY KEY,
            project_id  uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
            insight_id  uuid NOT NULL,
            user_id     uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
            verdict     text NOT NULL
                CONSTRAINT {TABLE}_verdict_check CHECK (verdict IN ('right', 'wrong')),
            note        text CONSTRAINT {TABLE}_note_check CHECK (char_length(note) <= 500),
            created_at  timestamptz NOT NULL DEFAULT now(),
            updated_at  timestamptz NOT NULL DEFAULT now(),
            CONSTRAINT {TABLE}_vote_key UNIQUE (project_id, insight_id, user_id)
        )
        """
    )
    op.execute(f"CREATE INDEX {TABLE}_user_idx ON {TABLE} (user_id)")
    op.execute(
        f"ALTER TABLE {TABLE} ADD CONSTRAINT {INSIGHT_FK} FOREIGN KEY (insight_id, project_id) "
        "REFERENCES insights (id, project_id) ON DELETE CASCADE NOT VALID"
    )
    _validate(TABLE, INSIGHT_FK)
    _enable_rls()


def _enable_rls() -> None:
    op.execute(f"ALTER TABLE {TABLE} ENABLE ROW LEVEL SECURITY")
    op.execute(f"ALTER TABLE {TABLE} FORCE ROW LEVEL SECURITY")
    op.execute(
        f"CREATE POLICY {TABLE}_project_isolation ON {TABLE} "
        f"USING ({PROJECT_EXPRESSION}) WITH CHECK ({PROJECT_EXPRESSION})"
    )
    op.execute(
        f"CREATE POLICY {TABLE}_worker_bypass ON {TABLE} "
        f"USING ({BYPASS_EXPRESSION}) WITH CHECK ({BYPASS_EXPRESSION})"
    )


# Copied on purpose into each migration that validates: migrations do not import app code or
# each other, so a later change to a shared helper cannot rewrite what a shipped one did.
def _validate(table: str, constraint: str) -> None:
    """Validate `constraint` against every row of `table`, whatever row-level security hides.

    Migrations run as the table owner, and FORCE ROW LEVEL SECURITY applies the policies to it:
    Postgres validates a foreign key with a query that sees only the rows the policies let
    through. (A CHECK is validated by scanning the table, which the policies do not filter; it
    goes through here too, so every validation follows one rule.) The worker bypass is set for
    the statement's own transaction and the caller's value restored afterwards; on an error the
    transaction aborts and discards the setting by itself. One `DO` block, so the setting and the
    validation share a transaction even inside `autocommit_block()`.
    """
    op.execute(
        f"""
        DO $$
        DECLARE
            previous text := current_setting('app.bypass_rls', true);
        BEGIN
            PERFORM set_config('app.bypass_rls', 'on', true);
            ALTER TABLE {table} VALIDATE CONSTRAINT {constraint};
            PERFORM set_config('app.bypass_rls', COALESCE(previous, ''), true);
        END
        $$
        """
    )


def downgrade() -> None:
    op.execute(f"SET LOCAL lock_timeout = '{LOCK_TIMEOUT}'")
    op.execute(f"DROP TABLE IF EXISTS {TABLE}")
